import * as THREE from 'three/webgpu';
import { color, uv, mix, step, smoothstep } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];
  const resources = [];

  const width = 2.6;
  const height = 0.68;
  const cornerRadius = 0.08;
  const depth = 0.03;

  // BUTTON GEOMETRY: Rounded rectangle extruded with chamfered edges
  const shape = new THREE.Shape();
  const x = -width / 2;
  const y = -height / 2;
  const w = width;
  const h = height;

  shape.moveTo(x + cornerRadius, y);
  shape.lineTo(x + w - cornerRadius, y);
  shape.quadraticCurveTo(x + w, y, x + w, y + cornerRadius);
  shape.lineTo(x + w, y + h - cornerRadius);
  shape.quadraticCurveTo(x + w, y + h, x + w - cornerRadius, y + h);
  shape.lineTo(x + cornerRadius, y + h);
  shape.quadraticCurveTo(x, y + h, x, y + h - cornerRadius);
  shape.lineTo(x, y + cornerRadius);
  shape.quadraticCurveTo(x, y, x + cornerRadius, y);

  const buttonGeom = new THREE.ExtrudeGeometry(shape, {
    depth: depth,
    bevelEnabled: true,
    bevelThickness: cornerRadius * 0.5,
    bevelSize: cornerRadius * 0.5,
    bevelSegments: 4
  });
  resources.push(buttonGeom);

  // MATERIAL: Engineered gradient + seam line with TSL
  const c1 = color(0xff4450);
  const c2 = color(0xff2a38);
  const c3 = color(0xc1121f);
  const seamCol = color(0xff2a38);

  const uvY = uv().y;
  const gradientBase = mix(c1, c2, smoothstep(0.0, 0.55, uvY));
  const gradient = mix(gradientBase, c3, smoothstep(0.55, 1.0, uvY));

  // Hard seam line at 50% (0.01 unit width in UV space)
  const seamMask = step(0.495, uvY).mul(step(uvY, 0.505));
  const baseColor = mix(gradient, seamCol, seamMask.mul(0.3));

  const material = new THREE.MeshStandardNodeMaterial({
    color: baseColor,
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22,
    emissive: color(0xff2a38),
    emissiveIntensity: 1.6,
    side: THREE.FrontSide
  });
  resources.push(material);

  const buttonMesh = new THREE.Mesh(buttonGeom, material);
  group.add(buttonMesh);

  // CONTACT SHADOW: Plane 0.08 units below
  const shadowGeom = new THREE.PlaneGeometry(width * 1.1, height * 1.1);
  resources.push(shadowGeom);

  const shadowMat = new THREE.MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35
  });
  resources.push(shadowMat);

  const shadowPlane = new THREE.Mesh(shadowGeom, shadowMat);
  shadowPlane.position.z = -0.08;
  group.add(shadowPlane);

  // TEXT: Label "BEGIN COMMISSION"
  const labelGeom = ctx.fontAtlas.createTextGeometry('BEGIN COMMISSION', {
    fontSize: 0.2,
    letterSpacing: 0.008,
    anchor: 'center'
  });
  resources.push(labelGeom);

  const textMat = new THREE.MeshStandardNodeMaterial({
    map: ctx.fontAtlas.texture,
    color: 0xe8ecf2,
    emissive: 0x000000,
    metalness: 0.1,
    roughness: 0.8,
    side: THREE.DoubleSide,
    transparent: true
  });
  resources.push(textMat);

  const labelMesh = new THREE.Mesh(labelGeom, textMat);
  labelMesh.position.y = 0;
  labelMesh.position.z = 0.025;
  group.add(labelMesh);

  // TEXT: Caption "NO DEPOSIT REQUIRED"
  const captionGeom = ctx.fontAtlas.createTextGeometry('NO DEPOSIT REQUIRED', {
    fontSize: 0.09,
    letterSpacing: 0.012,
    anchor: 'center'
  });
  resources.push(captionGeom);

  const captionMesh = new THREE.Mesh(captionGeom, textMat);
  captionMesh.position.y = -0.25;
  captionMesh.position.z = 0.025;
  group.add(captionMesh);

  // MOUNT ANIMATION: Weighted-settle scale 1.04 → 1.0
  group.scale.set(1.04, 1.04, 1.04);
  const mountTl = gsap.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)'
  });
  timelines.push(mountTl);

  // EVENT HANDLERS
  group.userData.handlers = {};

  const emissiveState = { intensity: 1.6 };

  group.userData.handlers.onPointerEnter = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    const tl = gsap.timeline();
    tl.to(
      buttonMesh.position,
      {
        z: 0.06,
        duration: 0.18,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
      },
      0
    );
    tl.to(
      emissiveState,
      {
        intensity: 2.2,
        duration: 0.18,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
        onUpdate: () => {
          material.emissiveIntensity = emissiveState.intensity;
        }
      },
      0
    );
    timelines.push(tl);
  };

  group.userData.handlers.onPointerLeave = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    const tl = gsap.timeline();
    tl.to(
      buttonMesh.position,
      {
        z: 0,
        duration: 0.18,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
      },
      0
    );
    tl.to(
      emissiveState,
      {
        intensity: 1.6,
        duration: 0.18,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
        onUpdate: () => {
          material.emissiveIntensity = emissiveState.intensity;
        }
      },
      0
    );
    timelines.push(tl);
  };

  group.userData.handlers.onPointerDown = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    const tl = gsap.timeline();
    tl.to(
      group.scale,
      {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)'
      },
      0
    );
    // Shadow tightens on press
    tl.to(
      shadowPlane.scale,
      {
        x: 0.8,
        y: 0.8,
        duration: 0.12,
        ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)'
      },
      0
    );
    timelines.push(tl);
  };

  group.userData.handlers.onPointerUp = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    const tl = gsap.timeline();
    tl.to(
      group.scale,
      {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)'
      },
      0
    );
    tl.to(
      shadowPlane.scale,
      {
        x: 1,
        y: 1,
        duration: 0.12,
        ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)'
      },
      0
    );
    timelines.push(tl);
  };

  // CLEANUP
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(buttonMesh.position);
    gsap.killTweensOf(shadowPlane.scale);
    gsap.killTweensOf(emissiveState);
    resources.forEach(res => res.dispose?.());
  };

  return group;
}
